#define assert(condition) ((void)0)

class HighScoreFrontEnd
{
public:
    static const int NUM_ROWS = 10;
};

struct HighScoreData
{
    char initials[4];
    char character[32];
    int score;
    int icons;
};

class GlobalDataClass
{
private:
    class BeachData
    {
    public:
        HighScoreData high_scores[HighScoreFrontEnd::NUM_ROWS];
        HighScoreData high_icons[HighScoreFrontEnd::NUM_ROWS];
        bool unlocked;
    };

    char data_before_globalBeaches[0x75C];
    BeachData globalBeaches[1];

public:
    void setBeachHighScore(int beach, int whichScore, bool icons, HighScoreData newScore);
};

void GlobalDataClass::setBeachHighScore(int beach, int whichScore, bool icons, HighScoreData newScore) 
{ 
    assert(beach < 32);
    if(icons)
        globalBeaches[beach].high_icons[whichScore] = newScore; 
    else globalBeaches[beach].high_scores[whichScore] = newScore; 
}
